import { solve } from "./solution.js";
function check(got: string, want: string, index: number): void {
  if (got !== want) throw new Error(`case ${index}`);
}
check(solve(""), "", 0);
check(solve("A"), "1A", 1);
check(solve("AA"), "2A", 2);
check(solve("AB"), "1A1B", 3);
check(solve("AAABB"), "3A2B", 4);
check(solve("ABBA"), "1A2B1A", 5);
check(solve("ZZZZZZZZZZZZ"), "12Z", 6);
check(solve("ABCABC"), "1A1B1C1A1B1C", 7);
check(solve("AAAABCCCC"), "4A1B4C", 8);
check(solve("AZZA"), "1A2Z1A", 9);
check(solve(""), "1000A", 10);
check(solve("XXYYYZ"), "2X3Y1Z", 11);
